func (s *store) put(k, v string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	// Ensure we are at the end, although O_APPEND should handle this.
	// However, Sync() might fail and leave the file in a state where we need to be careful.
	// If Sync() fails, we might have a partially written line.
	// The problem is that the next write might start after the partial write.
	// We need to truncate to the last known good line if a sync fails.

	if _, err := s.file.Seek(0, io.SeekEnd); err != nil {
		return err
	}

	// Save current position
	off, _ := s.file.Seek(0, io.SeekCurrent)

	if _, err := s.file.WriteString(k + "=" + v + "\n"); err != nil {
		s.file.Truncate(off)
		return err
	}

	if err := s.file.Sync(); err != nil {
		s.file.Truncate(off)
		return err
	}
	s.values[k] = v
	return nil
}

